 private String page(){return "<!doctype html><html><meta name='viewport' content='width=device-width,initial-scale=1'><link rel='stylesheet' href='styles.css'><body><div id='stage'><div id='owned' class='ss-beat on first-scene'></div></div><script>var PHOTOS="+deck+";function aspect(p){return p.w/p.h}function photoUrl(p){return p.url}</script><script src='lib-engine.js'></script><script src='modes.js'></script><script src='mode-impls.js'></script><script>\nvar ready=false,cleanup=null,svgDecoded=false,borderDecoded=false,borderImage=null,borderSrc='',borderAspect=0,token='"+sceneToken()+"';var svg=new Image();svg.onload=function(){svgDecoded=svg.naturalWidth===480&&svg.naturalHeight===360};svg.src='photo-doodles-dark.svg';requestAnimationFrame(function(){var root=document.getElementById('owned'),ctx={root:root,deck:PHOTOS,cursor:{i:"+photoIndex()+"},W:root.clientWidth,H:root.clientHeight,url:photoUrl,photoMotion:false,photoMs:600000,microMs:600000,motionMs:600000};cleanup=SS.MODES['"+mode()+"'].run(ctx,PHOTOS);cleanup.ready.then(function(ok){ready=ok===true})});\nfunction state(){var layer=document.querySelector('.ss-layer.on'),hero=layer&&layer.querySelector('.ss-hero'),border=hero&&hero.querySelector('.ss-photo-border');if(!layer||!hero||!border)return {ready:false};var r=hero.getBoundingClientRect(),br=border.getBoundingClientRect(),p=PHOTOS["+photoIndex()+"],fit=Math.min(r.width/p.w,r.height/p.h),cs=getComputedStyle(layer),bc=getComputedStyle(border),match=bc.backgroundImage.match(/^url\\([\"']?(.*?)[\"']?\\)$/),url=match?match[1]:'';if(url!==borderSrc){borderSrc=url;borderDecoded=false;borderImage=new Image();borderImage.onload=function(){borderDecoded=true;borderAspect=borderImage.naturalWidth/borderImage.naturalHeight};borderImage.src=url;}var expectedW=Math.min(1000,1000*aspect(p)),expectedH=expectedW/aspect(p);var expected='<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"'+expectedW+'\" height=\"'+expectedH+'\" viewBox=\"0 0 '+expectedW+' '+expectedH+'\"><rect width=\"100%\" height=\"100%\" fill=\"none\" stroke=\"#c7b79c\" stroke-opacity=\".92\" stroke-width=\"2\" vector-effect=\"non-scaling-stroke\"/></svg>';var valid=url.indexOf('data:image/svg+xml,')===0&&decodeURIComponent(url.substring(19))===expected;\nreturn {ready:ready,svgDecoded:svgDecoded,borderDecoded:borderDecoded,borderAspect:borderAspect,photoAspect:aspect(p),borderDataSvg:valid,borderSize:bc.backgroundSize,borderPosition:bc.backgroundPosition,borderRepeat:bc.backgroundRepeat,borderPointer:bc.pointerEvents,borderRectMatchesHero:Math.abs(r.x-br.x)<.05&&Math.abs(r.y-br.y)<.05&&Math.abs(r.width-br.width)<.05&&Math.abs(r.height-br.height)<.05,sceneToken:token,background:cs.backgroundImage,size:cs.backgroundSize,repeat:cs.backgroundRepeat,color:cs.backgroundColor,animation:cs.animationName,contain:getComputedStyle(hero).backgroundSize==='contain',heroAnimation:getComputedStyle(hero).animationName,photoBackground:hero.style.backgroundImage,fit:{x:r.x+(r.width-p.w*fit)/2,y:r.y+(r.height-p.h*fit)/2,w:p.w*fit,h:p.h*fit},dpr:devicePixelRatio,width:innerWidth,height:innerHeight};}\n</script></body></html>";}
