 String name=mode()+"-"+orientation()+(narrow()?"-narrow":"")+".png";try(OutputStream o=new FileOutputStream(new File(getExternalFilesDir(null),name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,o);}v.put("screenshot",name).put("pixelCopy",true).put("marginSamples",sampled).put("nonSolidMarginSamples",varying).put("dominantMarginColor",solid).put("dominantMarginSamples",dominant);observations.put(v);assertNativeBorder(bitmap,at,v);if(varying<100||dominant<sampled*.70)throw new IOException("no native margin marks against stable dominant color");scene++;if(scene<6){if(narrow()){FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(frame.getWidth()/2,-1,Gravity.CENTER);web.setLayoutParams(lp);attempt=0;h.postDelayed(this::poll,600);}else{web.setLayoutParams(new FrameLayout.LayoutParams(-1,-1));web.evaluateJavascript("cleanup();",x->start());}}else finishReport(null);
