 int[] expected={Color.GREEN,Color.BLUE,Color.YELLOW,Color.MAGENTA};JSONArray corners=new JSONArray(),edgeArray=new JSONArray();double cw=30.0/(photoIndex()==0?800:480),ch=30.0/(photoIndex()==0?500:800);for(int i=0;i<4;i++){int x=(int)Math.round(left+(right-left)*(i%2==0?cw:1-cw)),y=(int)Math.round(top+(bottom-top)*(i<2?ch:1-ch));int c=bitmap.getPixel(at[0]+x,at[1]+y),e=expected[i];boolean corner=Math.abs(Color.red(c)-Color.red(e))+Math.abs(Color.green(c)-Color.green(e))+Math.abs(Color.blue(c)-Color.blue(e))<=12;corners.put(corner);edgeArray.put(edges[i]);if(!corner)throw new IOException("photo corner missing "+i);if(edges[i]<20)throw new IOException("native warm border absent on edge "+i);}
